const watchlist = $json;
if (watchlist.schema_version !== 1 || !Array.isArray(watchlist.sources)) {
  throw new Error('Unsupported or invalid HomeCompute update-check watchlist');
}

const config = $('Configuration').first().json;
let overrides;
try {
  overrides = JSON.parse(config.pinned_overrides_json || '{}');
} catch (error) {
  throw new Error(`pinned_overrides_json must be valid JSON: ${error.message}`);
}
if (!overrides || Array.isArray(overrides) || typeof overrides !== 'object') {
  throw new Error('pinned_overrides_json must be a JSON object');
}

return watchlist.sources.map((source) => ({
  json: {
    ...source,
    pinned_marker: overrides[source.id] || '',
    checked_at: new Date().toISOString()
  }
}));

const sources = $('Prepare checks').all().map((item) => item.json);
const responses = $input.all();

return sources.map((source, index) => {
  const response = responses[index]?.json;
  const fail = (message) => ({
    json: { ...source, ok: false, error: String(message || 'Unknown upstream response error') }
  });

  if (!response || response.error) {
    return fail(response?.error?.message || response?.message || 'No response');
  }

  let marker;
  let observedVersion;
  let inventory;
  let detail;

  if (source.kind === 'huggingface_model') {
    marker = response.sha;
    observedVersion = response.sha ? response.sha.slice(0, 12) : '';
    detail = response.lastModified || response.createdAt || '';
  } else if (source.kind === 'huggingface_search') {
    if (!Array.isArray(response)) return fail('Expected a Hugging Face model array');
    inventory = response
      .filter((model) => model && model.id)
      .map((model) => ({ id: model.id, sha: model.sha || '', lastModified: model.lastModified || '' }))
      .sort((a, b) => a.id.localeCompare(b.id));
    marker = JSON.stringify(inventory.map((model) => [model.id, model.sha]));
    observedVersion = `${inventory.length} matching models`;
    detail = inventory
      .slice()
      .sort((a, b) => b.lastModified.localeCompare(a.lastModified))
      .slice(0, 5)
      .map((model) => model.id)
      .join(', ');
  } else if (source.kind === 'github_file') {
    if (!Array.isArray(response) || !response[0]?.sha) return fail('Expected a GitHub commit array');
    marker = response[0].sha;
    observedVersion = response[0].sha.slice(0, 12);
    detail = response[0].commit?.author?.date || '';
  } else if (source.kind === 'github_release') {
    marker = response.tag_name;
    observedVersion = response.tag_name || '';
    detail = response.published_at || response.created_at || '';
  } else {
    return fail(`Unsupported source kind: ${source.kind}`);
  }

  if (!marker) return fail('The upstream response did not contain a revision marker');
  return {
    json: { ...source, ok: true, marker, observed_version: observedVersion, detail, inventory }
  };
});

const observations = $input.all().map((item) => item.json);
const config = $('Configuration').first().json;
const persistent = $getWorkflowStaticData('global');
persistent.sources ||= {};

const baseline = [];
const changes = [];
const pinMismatches = [];
const errors = [];
const activeIds = new Set(observations.map((observation) => observation.id));

for (const observation of observations) {
  if (!observation.ok) {
    errors.push({
      id: observation.id,
      label: observation.label,
      error: observation.error,
      url: observation.project_url
    });
    continue;
  }

  const previous = persistent.sources[observation.id];
  if (!previous) {
    baseline.push({
      id: observation.id,
      label: observation.label,
      observed: observation.observed_version
    });
  } else if (previous.marker !== observation.marker) {
    const change = {
      id: observation.id,
      label: observation.label,
      role: observation.role,
      previous: previous.observed_version || String(previous.marker).slice(0, 12),
      current: observation.observed_version,
      detail: observation.detail,
      url: observation.project_url
    };

    if (observation.kind === 'huggingface_search') {
      const oldInventory = new Map((previous.inventory || []).map((model) => [model.id, model.sha]));
      const newInventory = new Map((observation.inventory || []).map((model) => [model.id, model.sha]));
      change.added = [...newInventory.keys()].filter((id) => !oldInventory.has(id));
      change.removed = [...oldInventory.keys()].filter((id) => !newInventory.has(id));
      change.updated = [...newInventory.keys()].filter((id) => oldInventory.has(id) && oldInventory.get(id) !== newInventory.get(id));
    }
    changes.push(change);
  }

  if (observation.pinned_marker && observation.marker !== observation.pinned_marker) {
    pinMismatches.push({
      id: observation.id,
      label: observation.label,
      configured_pin: observation.pinned_marker,
      upstream: observation.observed_version,
      url: observation.project_url
    });
  }

  persistent.sources[observation.id] = {
    marker: observation.marker,
    observed_version: observation.observed_version,
    inventory: observation.inventory,
    last_seen_at: observation.checked_at
  };
}

for (const id of Object.keys(persistent.sources)) {
  if (!activeIds.has(id)) delete persistent.sources[id];
}
persistent.last_run_at = new Date().toISOString();

const reportedErrors = config.report_check_errors ? errors : [];
const hasReport = changes.length > 0 || pinMismatches.length > 0 || reportedErrors.length > 0;
const lines = [
  `HomeCompute weekly update check: ${changes.length} upstream change(s), ${pinMismatches.length} pin mismatch(es), ${reportedErrors.length} check error(s).`,
  ...changes.map((change) => `CHANGED: ${change.label}: ${change.previous} -> ${change.current} (${change.url})`),
  ...pinMismatches.map((mismatch) => `PIN BEHIND: ${mismatch.label}: configured ${mismatch.configured_pin} / upstream ${mismatch.upstream} (${mismatch.url})`),
  ...reportedErrors.map((error) => `CHECK ERROR: ${error.label}: ${error.error} (${error.url})`),
  '',
  'Review only: verify provenance/license, exact GB10 recipe, image/runtime/parser tuple, per-alias benchmarks, capacity, and rollback before changing the setup.'
];

return [{
  json: {
    has_report: hasReport,
    checked_at: persistent.last_run_at,
    first_run_baselines: baseline,
    changes,
    pin_mismatches: pinMismatches,
    check_errors: errors,
    notification: {
      title: 'HomeCompute setup update review',
      text: lines.join('\n'),
      severity: reportedErrors.length > 0 ? 'warning' : 'info',
      review_only: true
    }
  }
}];
